<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {api,state} from '../lib'
import Modal from './Modal.vue'
import Icon from './Icon.vue'
import VirtualList from './VirtualList.vue'
import LocalDirectoryPicker from './LocalDirectoryPicker.vue'
import ExtensionPresets from './ExtensionPresets.vue'
import {entryIcon} from '../file-icon'
import {trackCASExport} from '../cas-export-jobs'
const props=defineProps({storage:String,source:String,sourceLabel:String,files:Array,selected:Array})
const emit=defineEmits(['close'])
const owner=state.username
const scope=ref(!props.selected.length),nodes=ref([]),directory=ref(''),extensions=ref(''),picker=ref(false),confirm=ref(false),busy=ref(false),error=ref(''),chosen=ref([...props.selected])
let alive=true
function make(files,parent=null){return files.map(f=>({file:f,parent,checked:true,open:false,children:null,loading:false}))}
const mixed=node=>node.children?.some(n=>n.checked||mixed(n))&&!node.checked
function toggle(node,value){node.checked=value;for(const child of node.children||[])toggle(child,value);for(let parent=node.parent;parent;parent=parent.parent)parent.checked=parent.children.every(n=>n.checked)}
async function expand(node){if(node.loading)return;if(node.children){node.open=!node.open;return}node.loading=true;try{const files=await api(`/files?storage=${encodeURIComponent(props.storage)}&path=${encodeURIComponent(node.file.id)}`);if(!alive)return;node.children=make(files,node);if(!node.checked)for(const child of node.children)toggle(child,false);node.open=true}catch(e){error.value=e.message}finally{node.loading=false}}
const rows=computed(()=>{const result=[];function walk(list,depth){for(const node of list){result.push({id:node.file.id,node,depth});if(node.open&&node.children)walk(node.children,depth+1)}}walk(nodes.value,0);return result})
const selectedLabels=computed(()=>{const labels=new Map();function walk(list,prefix){for(const node of list){const name=[prefix,node.file.name].filter(Boolean).join('/');labels.set(node.file.id,name);if(node.children)walk(node.children,name)}}walk(nodes.value,'');return chosen.value.map(id=>labels.get(id)||props.files.find(f=>f.id===id)?.name||id)})
function collect(){const ids=[];function walk(list){for(const node of list){if(node.children)walk(node.children);else if(node.checked)ids.push(node.file.id)}}walk(nodes.value);return ids}
function apply(){chosen.value=collect();scope.value=false}
let savePending,saveRunning=false,saveWaiters=[]
function remember(){savePending=directory.value;const promise=new Promise(resolve=>saveWaiters.push(resolve));if(!saveRunning)drain();return promise}
async function drain(){saveRunning=true;let ok=true;while(savePending!==undefined){const value=savePending;savePending=undefined;try{await api('/files/cas-export','PUT',{directory:value});if(alive)error.value=''}catch(e){ok=false;if(alive)error.value=e.message}}saveRunning=false;const waiters=saveWaiters;saveWaiters=[];waiters.forEach(resolve=>resolve(ok))}
async function exportFiles(){if(busy.value)return;busy.value=true;if(!await remember()||!alive||!state.authenticated||state.username!==owner){busy.value=false;return}error.value='';try{const job=await api('/files/cas-export/jobs','POST',{storageId:props.storage,source:props.source,ids:chosen.value,extensions:extensions.value,directory:directory.value,confirm:true});if(!alive||!state.authenticated||state.username!==owner)return;trackCASExport(job);confirm.value=false;emit('close')}catch(e){if(alive)error.value=e.message}finally{busy.value=false}}
onMounted(async()=>{nodes.value=make(props.files);try{const value=await api('/files/cas-export');if(alive)directory.value=value.directory||''}catch(e){error.value=e.message}})
onBeforeUnmount(()=>{alive=false})
</script>
<template>
<Modal v-if="scope" standard title="CAS导出范围" @close="emit('close')"><div class="modal-body cas-export-scope"><label class="export-all"><input type="checkbox" :checked="nodes.every(n=>n.checked)" :indeterminate="nodes.some(n=>n.checked||mixed(n))&&!nodes.every(n=>n.checked)" @change="nodes.forEach(n=>toggle(n,$event.target.checked))" />全部目录</label><p v-if="error" class="error-message" role="alert">{{error}}</p><VirtualList :items="rows" :row-height="42"><template #default="{item}"><div class="export-tree-row" :style="{paddingLeft:item.depth*18+'px'}"><button v-if="item.node.file.isDir" class="icon-btn" :aria-label="`${item.node.open?'折叠':'展开'} ${item.node.file.name}`" @click="expand(item.node)"><Icon :name="item.node.loading?'LoaderCircle':item.node.open?'ChevronDown':'ChevronRight'" :size="16" /></button><span v-else class="export-tree-indent" /><label><input type="checkbox" :aria-label="item.node.file.name" :checked="item.node.checked" :indeterminate="mixed(item.node)" @change="toggle(item.node,$event.target.checked)" /><Icon :name="entryIcon(item.node.file)" :size="18" /><span>{{item.node.file.name}}</span></label></div></template></VirtualList></div><footer class="modal-footer"><button class="btn" @click="emit('close')">取消</button><button class="btn primary" :disabled="!collect().length" @click="apply"><Icon name="Check" />确认范围</button></footer></Modal>
<Modal v-else standard title="导出CAS" @close="!busy&&emit('close')"><div class="modal-body cas-export-form"><label>所选目录路径<div class="export-path">{{sourceLabel||source}}<span v-for="label in selectedLabels" :key="label">{{label}}</span></div></label><div class="extension-field"><div class="extension-heading"><label for="cas-export-extensions">媒体扩展名</label><ExtensionPresets v-model="extensions" /></div><input id="cas-export-extensions" v-model="extensions" /></div><label>导出目录<div class="directory-input"><input v-model="directory" aria-label="导出目录" @blur="remember" @keydown.enter.prevent="remember" /><button class="icon-btn" aria-label="选择导出目录" @click="picker=true"><Icon name="FolderOpen" /></button></div></label><p v-if="error" class="error-message" role="alert">{{error}}</p></div><footer class="modal-footer"><button class="btn" :disabled="busy" @click="emit('close')">取消</button><button class="btn primary" :disabled="busy||!chosen.length" @click="confirm=true"><Icon name="Download" />导出</button></footer></Modal>
<LocalDirectoryPicker v-if="picker" :initial="directory" @select="directory=$event;picker=false;remember()" @close="picker=false" />
<Modal v-if="confirm" compact confirmation title="确认导出CAS" @close="!busy&&(confirm=false)"><div class="modal-body">确认导出所选范围的媒体CAS？{{directory?'保存到容器目录，不覆盖同名文件。':'通过浏览器下载。'}}源文件保持不变。<p v-if="error" class="error-message" role="alert">{{error}}</p></div><footer class="modal-footer"><button class="btn" :disabled="busy" @click="confirm=false">取消</button><button class="btn primary" :disabled="busy" @click="exportFiles"><Icon :name="busy?'LoaderCircle':'Check'" />{{busy?'导出中':'确认导出'}}</button></footer></Modal>
</template>
<style scoped>.cas-export-scope{height:min(55dvh,420px);display:flex;flex-direction:column;gap:14px}.export-all,.export-tree-row label{display:flex;flex-direction:row;align-items:center;gap:8px;min-width:0}.export-tree-row{height:42px;display:flex;align-items:center;gap:4px}.export-tree-row label{flex:1}.export-tree-row label span{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.export-tree-row .icon-btn,.export-tree-indent{width:24px;height:30px;flex:none}.cas-export-form{display:grid;gap:18px}.export-path{padding:12px;border:1px solid var(--border);background:var(--layer-item);border-radius:8px;overflow-wrap:anywhere;max-height:140px;overflow:auto}.export-path>span{display:block;font-size:13px;color:var(--muted);margin-top:6px}.extension-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.extension-field input{width:100%}</style>
